-- Only small published result tables. No raw ODS/period joins. Current business month (yesterday); do not fall back to an older month.
WITH latest AS(SELECT report_month,MAX(data_as_of) data_as_of FROM dm_tmp.maxyu_id_long_monitor_publish WHERE report_month=CAST(DATE_TRUNC('month',DATE_SUB(CURRENT_DATE(),INTERVAL 1 DAY)) AS DATE) GROUP BY report_month),
ready AS(SELECT p.* FROM dm_tmp.maxyu_id_long_monitor_publish p JOIN latest l ON p.report_month=l.report_month AND p.data_as_of=l.data_as_of)
SELECT r.report_month,r.data_as_of,p.published_at,p.config_version,p.config_sha256,
r.`月份`,r.`数据截止日`,r.`账龄`,r.`首分PK组`,r.`PK客群`,r.`分案量`,r.`分案金额_人民币`,r.`分案剩本_人民币`,r.`昨日实收_人民币`,r.`累计实收_人民币`,r.`MTD实收率`,r.`MTD剩本实收率`,r.`成本_人民币_估算`,r.`净实收_人民币_估算`,r.`净实收率_估算`,r.`净剩本实收率_估算`,r.`CPS_估算`,r.`回款案件数`,r.`案件回款率`,r.`案件量占比`,r.`分案金额占比`,r.`分案剩本占比`,r.`件均分案金额_人民币`,r.`件均分案剩本_人民币`,r.`平均首分DPD`,r.`平均已观察天数`,r.`最大单案实收占比`,r.`前三案件实收占比`,r.`已满7日案件量`,r.`冻结池7日实收率`,r.`冻结池7日剩本实收率`,r.`昨日收盘在手案件量`,r.`在手时长折算人天`,r.`电话拨打覆盖案件数`,r.`电话拨打覆盖率`,r.`电话双边接通案件数`,r.`电话接通覆盖率`,r.`电话拨打次数`,r.`电话双边接通率`,r.`振铃加通话小时`,r.`AI拨打次数`,r.`短信发送记录数`,r.`纯净有电话AI短信触达案件数`,r.`首分C1至3案件数`,r.`首分C4至6案件数`,r.`首分C7至10案件数`,r.`分案事件数`,r.`分入资产数`,r.`后续新增资产数`,r.`连续归户回流日志数`,r.`跨模式案件数`,r.`手工调案案件数`,r.`内催人工成本_人民币`,r.`内催人工按电话权重_对照`,r.`委外佣金计提_人民币`,r.`通讯成本_人民币`,r.`总部成本_人民币`,r.`合规培训成本_人民币`,r.`财务已列税金_人民币`,r.`不含总部成本_人民币_估算`,r.`不含总部净实收_人民币_估算`,r.`模型已覆盖成本_人民币`,r.`费用或关联待核案件数`,r.`新增剩本待核资产数`,r.`短信未匹配计费数`,r.`工具归属冲突数`,r.`财务费用缺口数`,r.`财务重复键数`,r.`费用分摊范围异常数`,r.`IM汇率缺口数`,r.`组织人数缺失暂用10人天数`,r.`回款早于日志时间记录数`,r.`财务费用更新时间`,r.`最早入组时间`,r.`最晚入组时间`,r.`初始冻结逾期本金_人民币`,r.`初始冻结剩本_人民币`,r.`成熟7日池实收_人民币`,r.`成熟7日池本金_人民币`,r.`成熟7日池剩本_人民币`,r.`组内前三案实收_人民币`,r.`正实收案件合计_人民币`,r.`期间日均时长在手`,r.`共享专催队列日均人数`,r.`印尼盾每人民币`,r.`成本口径说明`
FROM dm_tmp.maxyu_id_long_monitor_pk r JOIN ready p ON r.report_month=p.report_month AND r.data_as_of=p.data_as_of AND r.run_id=p.run_id
WHERE r.report_month=CAST(DATE_TRUNC('month',DATE_SUB(CURRENT_DATE(),INTERVAL 1 DAY)) AS DATE)
